const rows=$('sql_inv_raw').all().map(i=>i.json)
const ctx=$('get_contexto').first().json
const rd=ctx.report_data||{}
let mant={terminales:[],servidores:[]}
try{const mm=(rd.modules||{}).mantenimiento; if(mm){mant.terminales=(mm.terminales||[]).map(t=>t.hostname).filter(Boolean); mant.servidores=(mm.servidores||[]).map(s=>s.hostname).filter(Boolean)}}catch(_){}
const devices=rows.map(r=>({hostname:r.hostname,source:r.source,match:r.source_match,uuid:r.hardware_uuid||null,eset_uuid:r.eset_uuid||null,mac:r.mac||null,serial:r.bios_serial||null,os:r.os,server:/server/i.test(r.os||'')}))
const ci=v=>{const n=Number(v);return Number.isFinite(n)?n:0}
const contrato={servidores:ci(ctx.contrato_servidores)+ci(ctx.contrato_servidores_virt),estaciones:ci(ctx.contrato_estaciones)}
const datos=JSON.stringify({devices,mantenimiento:mant,contrato})
const INSTR="Sos experto en inventario de IT, analista del informe. Recib\u00eds dispositivos de DOS consolas (OCS y ESET) ya pre-cruzados; un mismo equipo f\u00edsico puede aparecer en VARIAS filas. Deduplic\u00e1 a la lista REAL de m\u00e1quinas f\u00edsicas y detect\u00e1 inconsistencias.\n\nReglas de identidad: misma m\u00e1quina si comparten hardware_uuid (incluso con bytes invertidos por endianness, ej \"71FB9E65-418C-031A\"=\"659EFB71-8C41-1A03\"), o mismo bios_serial no-basura, o MACs adyacentes (\u00faltimo byte \u00b11) con mismo serial = 2 NICs del mismo equipo. IGNOR\u00c1 uuids/seriales basura repetidos en m\u00e1quinas distintas (ej \"03000200-0400-0500-0006-000700080009\", claves Windows \"VK7JG-...\"). hostname = se\u00f1al d\u00e9bil (puede haber 2 m\u00e1quinas distintas con mismo hostname, ej SRV01 local y SRV01 nube). eset_uuid != hardware_uuid (no comparar). tipo \"servidor\" si OS contiene \"Server\". Compar\u00e1 vs contrato (faltan/sobran). En \"inconsistencias\": duplicados mal cruzados, equipos en una sola consola, conteos que no cierran, hostnames colisionando."
const fullPrompt=INSTR+"\n\nDatos (JSON):\n"+datos
return [{json:{fullPrompt,_nDevices:devices.length,_contrato:contrato}}]

const ctx=$('get_contexto').first().json
const rd=ctx.report_data||{}
let ag=null; try{ag=$('recon_agent').first().json}catch(_){}
const ai=ag&&(ag.output||ag)
let nDev=0; try{nDev=$('prep_ai').first().json._nDevices||0}catch(_){}
rd._aiDebug={nDevices:nDev,agentKeys:ag?Object.keys(ag):null,nEquipos:(ai&&ai.equipos&&ai.equipos.length)||0,raw:JSON.stringify(ag||null).slice(0,900)}
if(ai&&Array.isArray(ai.equipos)&&ai.equipos.length>0){
  rd.reconciliacionAi=ai
  if(rd.kpis&&ai.resumen&&typeof ai.resumen.servidores==='number') rd.kpis.servidores=ai.resumen.servidores
}
const modulos=(rd._meta&&rd._meta.modulos)||Object.keys(rd.modules||{})
return [{json:{reportData:rd,nc:ctx.nc,informeId:Number($('webhook_ia').first().json.body.informeId)||0,modulos}}]
